(()=>{'use strict';
const $=s=>document.querySelector(s);
const COMMON=['bite','dartfish','shell','cleaner','ray','puffer','octoguard'];
const UNCOMMON=['school','ink','current','heal','electric','remora','jelly','tidewall','reefstance','shellgrowth','shoalguard','followbite','moltscale','venombloom','shoalstep','venomfang','toxicarmor','weakambush','scalecharge','hunterfocus','marlin','harpoon','crackshell','weakpoint','kabutowari'];
const RARE=['whale','mimic','tsunami','manta','leviathan','abyssarmor','seamiracle','predation'];
const ABYSS=['lantern','voidjaw','coelacanth','shadoweel','cthulhu','abyssdance','curseward','abyssflame'];
const BOSS_RELICS=new Set(['呪海の炉','四皇の王冠','深淵炉心','次元圧縮','巨鯨の心臓','水圧変異','黄金王座','深海の鍵','深淵の紋章','深淵の瞳']);
const RELIC_PRICES={'漂流者の糸':85,'供物の真珠':88,'サイドパック':95,'呪紋の外殻':90,'航海羅針盤':75,'黄金炉':80,'珊瑚の護符':60,'古代の盾':98,'深海時計':70,'黒潮の鱗':96,'捕食者の眼':82,'毒腺の指輪':84,'スラッシュブースト':63,'オウムガイの護殻':80,'皇帝の骨片':105,'防毒ジャケット':68,'深海の血脈':65,'分厚い甲殻':92,'警鐘の巻貝':85,'深海の呼吸':120,'巨獣の顎':100,'VIPカード':110};
let advanceAfterClose=false,shopRemovedThisVisit=false,stock=null;
let keeperTimer=null;
const KEEPER={hello:['いらっしゃい！　今日もピカッといい品ぞろえだよ！','やあやあ！　見るだけでも大歓迎！','深い海ほど、掘り出し物が光るんだよ！'],card:['その一枚、きっといい仕事をするよ！','いい目をしてるねえ！　お買い上げありがとう！','デッキがまたひとつ強くなったね！'],relic:['おおっ、そいつは長い付き合いになりそうだ！','レリックは持っているだけで働く、えらい品だよ！'],poor:['おっと、金貨がもう少し必要みたい！','お財布も深呼吸中かな？　またおいで！'],choose:['じっくり選んでね。押した一枚だけが変わるよ！'],heal:['ぷくっと元気！　フグ店長の治療だよ！']};
function keeperSay(text){let e=$('#shopKeeperSpeech');if(!e)return;clearTimeout(keeperTimer);e.textContent=text;e.classList.remove('pop');void e.offsetWidth;e.classList.add('pop');keeperTimer=setTimeout(()=>e.classList.remove('pop'),2600);window.applyFuri?.(e)}
function game(){let g=window.getAbyssGame?.();if(g)g.upgrades||={};return g}
function syncShopResources(g=game()){if(!g)return;let hp=$('#shopHp'),gold=$('#shopPearls'),deck=$('#shopDeckCount');if(hp)hp.textContent=`${g.hp}/${g.max}`;if(gold)gold.textContent=g.pearl;if(deck)deck.textContent=g.deck.length}
function persist(){let g=game();if(!g)return;window.abyssSave?.();$('#hudHp').textContent=`${g.hp}/${g.max}`;$('#pearls').textContent=g.pearl;$('#deckCount').textContent=g.deck.length;syncShopResources(g);window.syncAbyssSystems?.()}
function spend(cost,action){let g=game();if(!g||g.pearl<cost){flash('金貨が足りない');keeperSay(KEEPER.poor[Math.random()*KEEPER.poor.length|0]);return false}g.pearl-=cost;action(g);persist();return true}
function flash(text){let e=$('#shopMessage');if(!e)return;e.textContent=text;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),1400)}
function cardData(k){let getter=window.getAbyssIntrinsicCardStats||window.getAbyssCardStats;return getter?.(k)||window.getAbyssCardData?.(k)||{n:k,t:'効果情報なし',c:0}}
function cardName(k){return cardData(k).n}
function cardEffect(k){return String(cardData(k).t||'').replace(/^強化済み：/,'')}
function rarity(c){return c.special?'特殊':c.a?'深淵':c.r?'レア':c.u?'アンコモン':'コモン'}
function price(base,g=game()){let mult=window.getAbyssShopPriceMultiplier?.(g)||1;if(g?.relic?.some(r=>r[1]==='VIPカード'))mult*=.7;return Math.max(5,Math.ceil(base*mult/5)*5)}
function cardPrice(k){let c=cardData(k),base=c.a?90:c.r?76:c.u?48:34,power=(c.d||0)*(c.h||1)+(c.b||0)+(c.p||0)*2+(c.he||0)*2+(c.dr||0)*7+(c.s||0)*10+(c.def||0)*10;return price(base+Math.min(20,Math.floor(power/8)*3))}
function removalBase(g=game()){return 40+Math.max(0,g?.removeCount||0)*20}
function take(pool,n){const tier=pool===COMMON?'common':pool===UNCOMMON?'uncommon':pool===RARE?'rare':'abyss';return window.extendAbyssCardPool(pool,tier).sort(()=>Math.random()-.5).slice(0,n)}
function pickRelicStock(pool){let byTier={common:[],uncommon:[],rare:[]};pool.forEach(n=>{let t=window.ABYSS_RELICS?.[n]?.[2];if(byTier[t])byTier[t].push(n)});let picks=[];['common','uncommon','rare'].forEach(t=>{if(byTier[t].length)picks.push(byTier[t][Math.random()*byTier[t].length|0])});let remaining=pool.filter(n=>!picks.includes(n)).sort(()=>Math.random()-.5);while(picks.length<3&&remaining.length)picks.push(remaining.shift());return picks.sort(()=>Math.random()-.5)}
function makeStock(){let g=game(),rareCount=Math.random()<.3?1:0,cards=g?.act>=2?[...take(COMMON,1),...take(UNCOMMON,4-rareCount),...take(RARE,rareCount),...take(ABYSS,1)]:[...take(COMMON,1),...take(UNCOMMON,5-rareCount),...take(RARE,rareCount)];cards=cards.map(k=>({k,price:cardPrice(k),sold:false}));let owned=new Set((g?.relic||[]).map(r=>r[1])),relicPool=Object.keys(window.ABYSS_RELICS||{}).filter(n=>!BOSS_RELICS.has(n)&&!owned.has(n)&&RELIC_PRICES[n]),relics=pickRelicStock(relicPool).map(name=>({name,price:price(RELIC_PRICES[name]),sold:false}));return{cards,relics}}
function render(){let g=game(),grid=$('#shopGrid');if(!g||!grid)return;grid.classList.remove('choosing');let removePrice=price(removalBase(g)),healPrice=price(25),upgradePrice=price(45),asc=(g.ascension||0)>=5,discount=g.relic.some(r=>r[1]==='VIPカード');if(!stock)stock=makeStock();$('#shopHp').textContent=`${g.hp}/${g.max}`;$('#shopPearls').textContent=g.pearl;grid.innerHTML=`
  ${(asc||discount)?`<div class="shop-adjust">${asc?'<span>深淵階級：価格＋15%</span>':''}${discount?'<span class="discount">🏮 VIP割引：価格−30%</span>':''}</div>`:''}
  <section class="shop-stock-section"><div class="shop-section-title"><b>🎴 カード市場</b><span>6枚の商品</span></div><p>店ごとに品ぞろえが変わり、効果とレアリティが高いカードほど高価です。</p><div class="shop-market unified-shop-market">${stock.cards.map((x,i)=>`<button class="market-item unified-market-item" data-card-stock="${i}" ${x.sold?'disabled':''}>${window.renderAbyssCardView?.(x.k,{sold:x.sold})||''}<strong class="shop-card-price">🪙 ${x.price}</strong></button>`).join('')}</div></section>
  <section class="shop-stock-section"><div class="shop-section-title"><b>🔱 レリック市場</b><span>${stock.relics.length}個の商品</span></div><p>この潜航で持っていないレリックだけが並びます。</p><div class="shop-market relic-market">${stock.relics.length?stock.relics.map((x,i)=>{let r=window.ABYSS_RELICS[x.name],label={common:'コモン',uncommon:'アンコモン',rare:'レア'}[r[2]];return `<button class="market-item relic-stock" data-relic-stock="${i}" ${x.sold?'disabled':''}><i>${r[0]}</i><b>${x.sold?'売り切れ':x.name}${label?`<span class="relic-rarity rarity-${r[2]}">${label}</span>`:''}</b><span>${r[1]}</span><small>🪙 ${x.price}</small></button>`}).join(''):'<p class="sold-out-note">購入できる未所持のレリックはありません。</p>'}</div></section>
  <button class="shop-item" data-buy="heal"><i>🫧</i><b>珊瑚の治療</b><span>HPを20回復</span><strong>🪙 ${healPrice}</strong></button>
  <button class="shop-item" data-buy="remove" ${shopRemovedThisVisit?'disabled':''}><i>✂️</i><b>カード削除</b><span>${shopRemovedThisVisit?'この店では削除済み':'使うたび基本価格が🪙 20上昇'}</span><strong>🪙 ${removePrice}</strong></button>
  <button class="shop-item upgrade-stock" data-buy="upgrade"><i>🔨</i><b>カード強化</b><span>指定した1枚の効果を永久に上げる</span><strong>🪙 ${upgradePrice}</strong></button>`;
  grid.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>buy(b.dataset.buy));
  grid.querySelectorAll('[data-card-stock]').forEach(b=>b.onclick=()=>buyCard(+b.dataset.cardStock));
  grid.querySelectorAll('[data-relic-stock]').forEach(b=>b.onclick=()=>buyRelic(+b.dataset.relicStock));
  window.polishShop?.(grid);window.applyFuri?.($('#shopModal'));
}
function choose(mode){let g=game();if(mode==='remove'&&shopRemovedThisVisit)return flash('この店でのカード削除は1回まで');keeperSay(KEEPER.choose[0]);syncShopResources(g);let cost=price(mode==='remove'?removalBase(g):45),nextCost=price(removalBase(g)+20),list=g.deck.map((k,i)=>({k,i})).filter(x=>mode==='remove'||((!x.k.includes('+')||cardData(x.k).stackableUpgrade)&&!cardData(x.k).special));$('#shopGrid').innerHTML=`<div class="shop-choose"><h3>${mode==='remove'?'削除するカード':'強化するカード'}を選ぶ</h3>${mode==='remove'?`<p class="shop-price-note">今回 🪙 ${cost}・次回 🪙 ${nextCost}</p>`:''}<div class="shop-card-list unified-shop-choice-list">${list.map(x=>{const compare=window.renderAbyssUpgradeComparison?.(x.k,'shop-upgrade-compare')||`<span class="effect-before">強化前：${cardEffect(x.k)}</span><span class="effect-after">強化後：${cardEffect(x.k+'+')}</span>`;return `<button class="shop-card unified-shop-choice ${mode==='upgrade'?'upgrade-option':''}" data-k="${x.k}" data-index="${x.i}">${window.renderAbyssCardView?.(x.k)||''}<strong class="shop-card-price">${mode==='remove'?'デッキから削除':`🪙 ${cost}`}</strong>${mode==='upgrade'?compare:''}</button>`}).join('')||'<p>選べるカードがありません。</p>'}</div><button class="btn shop-back" id="shopBack">市場へ戻る</button></div>`;$('#shopBack').onclick=render;document.querySelectorAll('.shop-card').forEach(b=>b.onclick=()=>{let k=b.dataset.k,index=+b.dataset.index;if(mode==='remove'&&g.deck.length<=5)return flash('カードは5枚より少なくできない');let done=spend(cost,gg=>{if(mode==='remove'){gg.deck.splice(index,1);gg.removeCount=(gg.removeCount||0)+1;shopRemovedThisVisit=true;flash(`${cardName(k)}を削除した`);keeperSay('すっきりしたデッキは、欲しい一枚を引きやすいよ！');window.showCardChange?.('カード削除完了',k)}else{gg.deck[index]=k+'+';flash(`${cardName(k)}を1枚強化した`);keeperSay('カンカン、完成！　強くなった値も見てね！');window.showCardUpgrade?.(k)}});if(done&&mode==='upgrade')choose('upgrade');else render()});window.applyFuri?.($('#shopModal'))}
function buyCard(i){openCardPurchaseConfirm(i)}
function buyRelic(i){let x=stock?.relics[i],g=game();if(!x||x.sold||!g)return;if(g.relic.some(r=>r[1]===x.name))return flash('そのレリックはすでに持っている');let r=window.ABYSS_RELICS?.[x.name]||['🔱',''];openShopActionConfirm({eyebrow:'RELIC PURCHASE',title:'このレリックを購入しますか？',content:`<div class="shop-confirm-relic"><i>${r[0]}</i><b>${x.name}</b><span>${r[1]}</span></div>`,message:`🪙 ${x.price}を使います（所持 🪙 ${g.pearl}）`,confirmText:'購入',disabled:g.pearl<x.price,onConfirm:()=>{let current=stock?.relics[i],gg=game();if(!current||current.sold||current.name!==x.name||!gg)return render();if(gg.pearl<current.price){flash('金貨が足りない');keeperSay(KEEPER.poor[0]);return false}if(window.acquireAbyssRelic?.(current.name)===false){flash('レリックを購入できなかった');return false}gg.pearl-=current.price;current.sold=true;if(current.name==='VIPカード'){stock.cards.filter(y=>!y.sold).forEach(y=>y.price=cardPrice(y.k));stock.relics.filter(y=>!y.sold).forEach(y=>y.price=price(RELIC_PRICES[y.name]))}persist();flash(`レリック「${current.name}」を手に入れた`);keeperSay(KEEPER.relic[Math.random()*KEEPER.relic.length|0]);render()}})}
function buy(type){let g=game();if(type==='heal'&&g.hp>=g.max)return flash('HPは満タンです');if(type==='heal'){let cost=price(25);return openShopActionConfirm({eyebrow:'CORAL TREATMENT',title:'HPを回復しますか？',content:`<div class="shop-confirm-service"><i>🫧</i><b>珊瑚の治療</b><span>HP ${g.hp}/${g.max} → ${Math.min(g.max,g.hp+20)}/${g.max}</span></div>`,message:`🪙 ${cost}を使います（所持 🪙 ${g.pearl}）`,confirmText:'回復する',disabled:g.pearl<cost,onConfirm:()=>{let done=spend(cost,gg=>{gg.hp=Math.min(gg.max,gg.hp+20);flash('HPを回復した');keeperSay(KEEPER.heal[0])});if(done)render();return done}})}if(type==='remove')return choose('remove');if(type==='upgrade')return choose('upgrade')}
function close(){let m=$('#shopModal');m.classList.remove('on');if(advanceAfterClose){advanceAfterClose=false;window.abyssAdvance?.()}}
window.openAbyssShop=(advance=false)=>{advanceAfterClose=advance;shopRemovedThisVisit=false;stock=makeStock();render();$('#shopModal').classList.add('on');let g=game(),vip=g?.relic?.some(r=>r[1]==='VIPカード');keeperSay(vip?'おっと、VIPのお客様じゃないか！　今日は特別に良い物ばかり並べておいたよ！':KEEPER.hello[Math.random()*KEEPER.hello.length|0]);window.applyFuri?.($('#shopModal'))};
let modal=document.createElement('div');modal.className='modal';modal.id='shopModal';modal.innerHTML='<div class="panel shop-panel"><div class="shop-head"><div><small>ABYSS BAZAAR</small><h2>深海商店</h2></div><div class="shop-resources"><button class="shop-deck-view" id="shopDeckView">🎴 デッキ <span id="shopDeckCount">0</span></button><div class="shop-wallet">❤️ <span id="shopHp">0/0</span></div><div class="shop-wallet">🪙 <span id="shopPearls">0</span></div></div></div><div class="shop-keeper"><div class="keeper-speech" id="shopKeeperSpeech">いらっしゃい！</div><img src="assets/ui/puffer-shopkeeper-v2.webp" alt="写真のフグを参考にしたフグ店長"></div><p>金貨で、必要なカードやレリックを選ぼう。</p><div id="shopMessage"></div><div class="shop-grid" id="shopGrid"></div><button class="btn gold shop-exit" id="shopClose">店を出る</button></div>';document.body.appendChild(modal);$('#shopClose').onclick=()=>openShopActionConfirm({eyebrow:'LEAVE SHOP',title:'店を出ますか？',message:'現在の品ぞろえには戻れません。',confirmText:'店を出る',onConfirm:close});$('#shopDeckView').onclick=()=>{let collection=$('#collectionModal');collection?.classList.add('shop-deck-preview');$('#deckView')?.click()};$('#collectionClose')?.addEventListener('click',()=>$('#collectionModal')?.classList.remove('shop-deck-preview'));modal.onclick=e=>{if(e.target===modal)$('#shopClose').click()};
let upgradeConfirm=document.createElement('div');upgradeConfirm.className='modal shop-upgrade-confirm';upgradeConfirm.id='shopUpgradeConfirm';upgradeConfirm.innerHTML='<div class="panel shop-upgrade-confirm-panel"><small>UPGRADE PREVIEW</small><h2>このカードを強化しますか？</h2><div id="shopUpgradeConfirmCards"></div><p id="shopUpgradeConfirmPrice"></p><div class="shop-upgrade-confirm-actions"><button class="btn" id="shopUpgradeCancel">やめる</button><button class="btn gold" id="shopUpgradeApply">強化する</button></div></div>';document.body.appendChild(upgradeConfirm);
let purchaseConfirm=document.createElement('div');purchaseConfirm.className='modal shop-purchase-confirm';purchaseConfirm.id='shopPurchaseConfirm';purchaseConfirm.innerHTML='<div class="panel shop-purchase-confirm-panel"><small>CARD PURCHASE</small><h2>このカードを購入しますか？</h2><div id="shopPurchaseConfirmCard"></div><p id="shopPurchaseConfirmPrice"></p><div class="shop-purchase-confirm-actions"><button class="btn" id="shopPurchaseCancel">やめる</button><button class="btn gold" id="shopPurchaseApply">購入</button></div></div>';document.body.appendChild(purchaseConfirm);
let actionConfirm=document.createElement('div');actionConfirm.className='modal shop-purchase-confirm shop-action-confirm';actionConfirm.id='shopActionConfirm';actionConfirm.innerHTML='<div class="panel shop-purchase-confirm-panel"><small id="shopActionEyebrow">SHOP ACTION</small><h2 id="shopActionTitle"></h2><div id="shopActionContent"></div><p id="shopActionMessage"></p><div class="shop-purchase-confirm-actions"><button class="btn" id="shopActionCancel">やめる</button><button class="btn gold" id="shopActionApply">実行する</button></div></div>';document.body.appendChild(actionConfirm);
function openShopActionConfirm({eyebrow='SHOP ACTION',title,content='',message='',confirmText='実行する',disabled=false,onConfirm}){$('#shopActionEyebrow').textContent=eyebrow;$('#shopActionTitle').textContent=title;$('#shopActionContent').innerHTML=content;$('#shopActionMessage').textContent=message;let apply=$('#shopActionApply');apply.textContent=confirmText;apply.disabled=disabled;apply.onclick=()=>{let done=onConfirm?.();if(done===false)return;actionConfirm.classList.remove('on')};actionConfirm.classList.add('on');window.applyFuri?.(actionConfirm)}
$('#shopActionCancel').onclick=()=>actionConfirm.classList.remove('on');actionConfirm.onclick=e=>{if(e.target===actionConfirm)actionConfirm.classList.remove('on')};
function openCardPurchaseConfirm(i){let x=stock?.cards[i],g=game();if(!x||x.sold||!g)return;$('#shopPurchaseConfirmCard').innerHTML=window.renderAbyssCardView?.(x.k)||'';$('#shopPurchaseConfirmPrice').textContent=`🪙 ${x.price}を使います（所持 🪙 ${g.pearl}）`;let apply=$('#shopPurchaseApply');apply.disabled=g.pearl<x.price;apply.textContent='購入';apply.onclick=()=>{let current=stock?.cards[i];if(!current||current.sold||current.k!==x.k){purchaseConfirm.classList.remove('on');return render()}let done=spend(current.price,gg=>{gg.deck.push(current.k);current.sold=true;window.showCardAcquired?.(current.k,'ショップでカードを購入');flash(`${cardName(current.k)}を手に入れた`);keeperSay(KEEPER.card[Math.random()*KEEPER.card.length|0])});if(!done)return;purchaseConfirm.classList.remove('on');render()};purchaseConfirm.classList.add('on');window.applyFuri?.(purchaseConfirm)}
$('#shopPurchaseCancel').onclick=()=>purchaseConfirm.classList.remove('on');purchaseConfirm.onclick=e=>{if(e.target===purchaseConfirm)purchaseConfirm.classList.remove('on')};
function openRemovalConfirm(k,index){let g=game(),cost=price(removalBase(g));if(!g||g.deck[index]!==k)return choose('remove');if(g.deck.length<=5)return flash('カードは5枚より少なくできない');openShopActionConfirm({eyebrow:'CARD REMOVAL',title:'このカードを削除しますか？',content:`<div class="shop-confirm-card">${window.renderAbyssCardView?.(k)||''}</div>`,message:`🪙 ${cost}を使います（所持 🪙 ${g.pearl}）`,confirmText:'削除する',disabled:g.pearl<cost,onConfirm:()=>{if(game()?.deck?.[index]!==k)return choose('remove');let done=spend(cost,gg=>{gg.deck.splice(index,1);gg.removeCount=(gg.removeCount||0)+1;shopRemovedThisVisit=true;flash(`${cardName(k)}を削除した`);keeperSay('すっきりしたデッキは、欲しい一枚を引きやすいよ！');window.showCardChange?.('カード削除完了',k)});if(done)render();return done}})}
function openUpgradeConfirm(k,index){let g=game(),cost=price(45),before=window.renderAbyssCardView?.(k)||'',after=window.renderAbyssCardView?.(k+'+')||'';if(!g||g.deck[index]!==k)return choose('upgrade');$('#shopUpgradeConfirmCards').innerHTML=`<div class="shop-upgrade-card-pair"><div><small>強化前</small>${before}</div><b aria-hidden="true">→</b><div><small>強化後</small>${after}</div></div>`;$('#shopUpgradeConfirmPrice').textContent=`🪙 ${cost}を使います（所持 🪙 ${g.pearl}）`;$('#shopUpgradeApply').disabled=g.pearl<cost;$('#shopUpgradeApply').onclick=()=>{if(game()?.deck?.[index]!==k){upgradeConfirm.classList.remove('on');return choose('upgrade')}let done=spend(cost,gg=>{gg.deck[index]=k+'+';flash(`${cardName(k)}を1枚強化した`);keeperSay('カンカン、完成！　強くなった値も見てね！')});if(!done)return;upgradeConfirm.classList.remove('on');choose('upgrade');window.showCardUpgrade?.(k)};upgradeConfirm.classList.add('on');window.applyFuri?.(upgradeConfirm)}
$('#shopUpgradeCancel').onclick=()=>upgradeConfirm.classList.remove('on');upgradeConfirm.onclick=e=>{if(e.target===upgradeConfirm)upgradeConfirm.classList.remove('on')};$('#shopGrid').addEventListener('click',e=>{let b=e.target.closest('.shop-card');if(!b)return;e.preventDefault();e.stopImmediatePropagation();if(b.classList.contains('upgrade-option'))openUpgradeConfirm(b.dataset.k,+b.dataset.index);else openRemovalConfirm(b.dataset.k,+b.dataset.index)},true);
window.addEventListener('pageshow',()=>{$('#endTurn')?.removeAttribute('disabled')});
})();
